package dashboard

const employeePage = `
<section class="panel full" id="employee" aria-labelledby="employee-heading"><div class="panel-head"><div><p class="eyebrow">Employee / Recorded ledger</p><h2 id="employee-heading">Employee ledger</h2></div><div><label>Kind<select id="ledger-kind"><option value="">All records</option><option value="task">Tasks / turns</option><option value="resume">Resumes</option><option value="refusal">Refusals</option><option value="judgment">TypeSafe judgments</option><option value="proposal">Proposals</option><option value="tool">Tools</option><option value="decision">Decisions</option><option value="message">Messages</option></select></label><label>Since<input id="ledger-since" type="date"></label></div></div><p class="error" id="ledger-error"></p><div class="body" id="ledger-content"><p class="muted">Open an org node, then choose Employee ledger to read its records.</p></div></section>
`

const employeeScript = `
let employeeSelection=null,employeeData=null;
function ledgerPath(){if(!employeeSelection)return '';const query=new URLSearchParams(employeeSelection);if(byId('ledger-since').value)query.set('since',byId('ledger-since').value);return '/api/ledger?'+query.toString();}
function renderLedger(data){employeeData=data;const root=byId('ledger-content');setText(byId('employee-heading'),tr('{name} / Ledger',{name:data.employee.id}));if(!data.available){root.replaceChildren(node('p','No records for this employee in the selected period. Tasks, turns and messages appear when the launcher records them.','muted'));return;}const summary=data.summary,line=node('p',undefined,'numeric');setText(line,tr('Done {done} · Failed {failed} · Running {running} · Success {success} · Median {median} s · Tokens in/out/cached {input} / {output} / {cached} · USD {cost} · Resumes {resumes} · Refusals {refusals} · Messages sent/received {sent} / {received}{partial}',{done:measured(summary.tasks_done),failed:measured(summary.tasks_failed),running:measured(summary.tasks_running),success:summary.success_rate===null?tr('no data'):pct(summary.success_rate),median:measured(summary.median_duration_seconds),input:measured(summary.input_tokens),output:measured(summary.output_tokens),cached:measured(summary.cached_tokens),cost:measured(summary.cost_usd),resumes:measured(summary.resumes),refusals:measured(summary.refusals),sent:measured(summary.messages_sent),received:measured(summary.messages_received),partial:summary.usage_partial?tr(' · Usage partial'):''}));const trends=node('div',undefined,'analytics-grid');['tasks','success_rate'].forEach(field=>{const box=node('div',undefined,'analytics-block');box.append(node('h3',field==='tasks'?'Recorded turns per day':'Success rate per day'));box.append(sparkline(data.trend.filter(r=>r[field]!==null).map(r=>({time:r.day+'T00:00:00Z',value:field==='success_rate'?r[field]*100:r[field],source:r.source})),field==='tasks'?'Tasks per day':'Success rate (%)'));trends.append(box);});const target=node('div',undefined,'scroll metric-links');target.id='ledger-table';root.replaceChildren(line,trends,target);const filter=byId('ledger-kind').value,rows=data.rows.filter(r=>!filter||r.kind===filter);table('ledger-table',['Time','Kind / lane / turn','Brief / event','Outcome / reason','Exit / duration','Model / seat','Tokens / USD','Records'],rows.map(r=>({cells:[stamp(r.time),r.kind+' / '+value(r.lane)+(r.run?' / '+r.run:''),r.brief_title||(r.kind==='proposal'?value(r.rule_id)+' · '+value(r.note):r.kind==='tool'?value(r.path)+' · '+value(r.purpose):r.kind==='judgment'?value(r.ask)+' · '+r.answer.type+' / '+measured(r.answer.probability):r.rule_id)||(r.decision_ids||[]).join(', ')||(r.from?value(r.from)+' → '+value(r.to):'—'),r.outcome?node('span',stateText(r.outcome)):r.reason||r.action||'—',r.kind==='judgment'?node('span',tr('{value} ms',{value:measured(r.latency_ms)})):pairCell(measured(r.exit_code),measured(r.duration_seconds)),value(r.model)+' / '+value(r.account),r.kind==='task'?node('span',tr('{input} / {output} / {cached} · {cost}',{input:measured(r.input_tokens),output:measured(r.output_tokens),cached:measured(r.cached_tokens),cost:measured(r.cost_usd)})):'—',sourceLink(r.source)],classes:['nowrap','','summary','','nowrap','model','','']})),'No records match this kind filter.');}
function openEmployee(record){employeeSelection=record.kind==='lane'?{lane:record.name}:{instance:record.name};employeeData=null;byId('ledger-content').replaceChildren(node('p','Reading the employee’s recorded work…','muted'));panelDigests.delete('ledger');history.replaceState(null,'','#employee?'+new URLSearchParams(employeeSelection));fetchPanel('ledger',ledgerPath,renderLedger,true);}
const ledgerButton=node('button','Employee ledger');ledgerButton.type='button';ledgerButton.id='drawer-ledger';byId('drawer-close').before(ledgerButton);ledgerButton.addEventListener('click',()=>{if(drawerSelection)openEmployee(drawerSelection);byId('agent-drawer').close();goPanel('employee');});
byId('ledger-kind').addEventListener('change',()=>{if(employeeData)renderLedger(employeeData);});
byId('ledger-since').addEventListener('change',()=>{panelDigests.delete('ledger');fetchPanel('ledger',ledgerPath,renderLedger,true);});
panels.push(['ledger',ledgerPath,renderLedger]);
if(location.hash.startsWith('#employee?')){const query=new URLSearchParams(location.hash.slice(10));const lane=query.get('lane'),instance=query.get('instance');if(lane||instance)employeeSelection=lane?{lane}:{instance};}
`
